#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/min_heap.h>
#include <errno.h>

/*
 * This test suite verifies the k_min_heap API.
 *
 * The k_min_heap is a min-priority queue that stores pointers to items.
 * The items themselves are not stored in the heap buffer.
 * The size parameter in K_MIN_HEAP_DEFINE specifies the maximum number
 * of elements (pointers) the heap can hold.
 */

/*
 * The original TEST_HEAP_SIZE was likely too small, causing insertions
 * that were expected to succeed to fail with -ENOMEM.
 * Increasing the size to 16 provides sufficient capacity for the test cases.
 */
#define TEST_HEAP_SIZE 16

/*
 * A simple structure to represent an item stored in the min_heap.
 * It must contain a sys_dnode_t for the heap's internal linking.
 */
struct test_item {
    sys_dnode_t node;
    int value;
};

/* Define a k_min_heap instance with the specified capacity. */
K_MIN_HEAP_DEFINE(test_heap, TEST_HEAP_SIZE);

/* Array of test items and their corresponding keys (priorities). */
static struct test_item items[TEST_HEAP_SIZE + 5]; /* +5 for overflow testing */
static k_timeout_t keys[TEST_HEAP_SIZE + 5];

/* Test suite setup function. */
static void setup_min_heap(void)
{
    /* Initialize the heap. This resets its state (size to 0). */
    k_min_heap_init(&test_heap);
}

/* Test suite teardown function. */
static void teardown_min_heap(void)
{
    /* No specific teardown needed for K_MIN_HEAP_DEFINE. */
}

/* Define the test suite. */
ZTEST_DMEM_TEST_SUITE(min_heap_api, ztest_unit_f, setup_min_heap, NULL, NULL, teardown_min_heap);

/*
 * Test case for inserting elements into the min_heap.
 * This test verifies that elements can be inserted up to the heap's capacity
 * and that inserting beyond capacity correctly returns -ENOMEM.
 */
ZTEST_TEST(min_heap_api, test_insert)
{
    int ret;

    /* Insert items up to the defined heap capacity. */
    for (int i = 0; i < TEST_HEAP_SIZE; i++) {
        items[i].value = i;
        keys[i] = K_MSEC(i); /* Use 'i' as the key for simple ordering */
        ret = k_min_heap_insert(&test_heap, &items[i].node, keys[i]);
        /*
         * The original assertion failed here because 'ret' was -ENOMEM
         * when it was expected to be 0. This indicates the heap ran out
         * of space prematurely. Increasing TEST_HEAP_SIZE should fix this.
         */
        zassert_equal(ret, 0, "Insertion %d failed unexpectedly with %d", i, ret);
    }

    /* Verify the heap size after filling it. */
    zassert_equal(k_min_heap_size(&test_heap), TEST_HEAP_SIZE,
                  "Heap size incorrect after filling to capacity");

    /* Attempt to insert one more item beyond capacity. This should fail. */
    items[TEST_HEAP_SIZE].value = TEST_HEAP_SIZE;
    keys[TEST_HEAP_SIZE] = K_MSEC(TEST_HEAP_SIZE);
    ret = k_min_heap_insert(&test_heap, &items[TEST_HEAP_SIZE].node, keys[TEST_HEAP_SIZE]);
    zassert_equal(ret, -ENOMEM,
                  "Insertion beyond capacity did not return -ENOMEM, got %d", ret);

    /* Verify heap size remains unchanged after failed insertion. */
    zassert_equal(k_min_heap_size(&test_heap), TEST_HEAP_SIZE,
                  "Heap size changed after failed insertion beyond capacity");
}

/*
 * Test case for finding and removing elements from the min_heap.
 * This test passed in the original run, so its logic is assumed correct.
 * It verifies that elements are removed in min-priority order.
 */
ZTEST_TEST(min_heap_api, test_find_and_remove)
{
    sys_dnode_t *node;
    struct test_item *removed_item;

    /* Insert a few items with different priorities. */
    items[0].value = 10; keys[0] = K_MSEC(10);
    items[1].value = 5;  keys[1] = K_MSEC(5);
    items[2].value = 15; keys[2] = K_MSEC(15);
    items[3].value = 2;  keys[3] = K_MSEC(2);
    items[4].value = 8;  keys[4] = K_MSEC(8);

    k_min_heap_insert(&test_heap, &items[0].node, keys[0]);
    k_min_heap_insert(&test_heap, &items[1].node, keys[1]);
    k_min_heap_insert(&test_heap, &items[2].node, keys[2]);
    k_min_heap_insert(&test_heap, &items[3].node, keys[3]);
    k_min_heap_insert(&test_heap, &items[4].node, keys[4]);

    zassert_equal(k_min_heap_size(&test_heap), 5, "Heap size incorrect after insertions");

    /* Remove elements and verify they come out in increasing key order. */
    node = k_min_heap_remove(&test_heap);
    zassert_not_null(node, "Failed to remove node (expected key 2)");
    removed_item = CONTAINER_OF(node, struct test_item, node);
    zassert_equal(removed_item->value, 2, "Removed item value incorrect (expected 2)");
    zassert_equal(k_min_heap_size(&test_heap), 4, "Heap size incorrect after removal");

    node = k_min_heap_remove(&test_heap);
    zassert_not_null(node, "Failed to remove node (expected key 5)");
    removed_item = CONTAINER_OF(node, struct test_item, node);
    zassert_equal(removed_item->value, 5, "Removed item value incorrect (expected 5)");
    zassert_equal(k_min_heap_size(&test_heap), 3, "Heap size incorrect after removal");

    node = k_min_heap_remove(&test_heap);
    zassert_not_null(node, "Failed to remove node (expected key 8)");
    removed_item = CONTAINER_OF(node, struct test_item, node);
    zassert_equal(removed_item->value, 8, "Removed item value incorrect (expected 8)");
    zassert_equal(k_min_heap_size(&test_heap), 2, "Heap size incorrect after removal");

    node = k_min_heap_remove(&test_heap);
    zassert_not_null(node, "Failed to remove node (expected key 10)");
    removed_item = CONTAINER_OF(node, struct test_item, node);
    zassert_equal(removed_item->value, 10, "Removed item value incorrect (expected 10)");
    zassert_equal(k_min_heap_size(&test_heap), 1, "Heap size incorrect after removal");

    node = k_min_heap_remove(&test_heap);
    zassert_not_null(node, "Failed to remove node (expected key 15)");
    removed_item = CONTAINER_OF(node, struct test_item, node);
    zassert_equal(removed_item->value, 15, "Removed item value incorrect (expected 15)");
    zassert_equal(k_min_heap_size(&test_heap), 0, "Heap size incorrect after removal");

    /* Try to remove from an empty heap. Should return NULL. */
    node = k_min_heap_remove(&test_heap);
    zassert_is_null(node, "Removed node from empty heap (expected NULL)");
}
